using Microsoft.Extensions.Logging;

namespace Pragmatic.Logging.Benchmarks.Modules;

/// <summary>
///     Two of <c>ActionInvokerBase</c>'s methods as Pragmatic.Actions declared them before #114: generated by
///     Microsoft, written fully qualified for that reason. Instance methods finding the logger in a
///     <c>_logger</c> field, as the invoker's do.
/// </summary>
internal sealed partial class ActionsMicrosoftLog(ILogger logger)
{
    private readonly ILogger _logger = logger;

    [Microsoft.Extensions.Logging.LoggerMessage(Level = LogLevel.Debug, Message = ActionsCallSiteLog.StartTemplate)]
    public partial void LogStart(string kind, string actionName);

    [Microsoft.Extensions.Logging.LoggerMessage(Level = LogLevel.Information, Message = ActionsCallSiteLog.SuccessTemplate)]
    public partial void LogSuccess(string kind, string actionName, long elapsedMs);
}
